WITH valid AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, LENGTH(txn_type) AS txn_type_length, CAST(txn_time AS DATE) AS txn_time_day, COALESCE(merchant, 'DIRECT') AS merchant_clean FROM transactions WHERE amount BETWEEN 2400 AND 2700), ranked AS (SELECT id, txn_type, merchant FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_type_length NULLS LAST, id) = 1), cleaned AS (SELECT *, COALESCE(merchant, 'unassigned') AS merchant_filled, COALESCE(merchant, 'DIRECT') AS merchant_filled_2 FROM ranked WHERE merchant IS NOT NULL), cleaned_transactions AS (SELECT *, LENGTH(merchant) AS merchant_length FROM cleaned WHERE txn_type NOT IN ('FEE', 'CREDIT')), ranked_transactions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant, txn_type ORDER BY merchant_length DESC NULLS FIRST, id) AS latest_rank FROM cleaned_transactions) t WHERE latest_rank = 1), metrics AS (SELECT *, LEAD(merchant_length, 1) OVER (ORDER BY latest_rank, id) AS next_merchant_length, COUNT(merchant_length) OVER (PARTITION BY txn_type, merchant) AS txn_type_count_merchant_length, AVG(merchant_length) OVER (PARTITION BY txn_type ORDER BY merchant_length, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS merchant_length_avg_2, STDDEV_SAMP(merchant_length) OVER (PARTITION BY merchant, txn_type) AS merchant_stddev_samp_merchant_length FROM ranked_transactions), metrics_transactions AS (SELECT *, NTILE(5) OVER (PARTITION BY txn_type ORDER BY merchant_length_avg_2 DESC, id) AS merchant_length_avg_2_bucket, LAST_VALUE(next_merchant_length, TRUE) OVER (PARTITION BY merchant, txn_type ORDER BY latest_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_next_merchant_length FROM metrics WHERE txn_type_count_merchant_length <> 5) SELECT id, txn_type, merchant_filled, merchant_length, latest_rank, txn_type_count_merchant_length, merchant_length_avg_2, merchant_stddev_samp_merchant_length, last_known_next_merchant_length FROM metrics_transactions;
